def transform(grid):
    h, w = len(grid), len(grid[0])
    frame = grid[0][0]

    # The panel's left and right borders are full-height frame-color columns.
    border_cols = [c for c in range(w) if all(grid[r][c] == frame for r in range(h))]
    panel_w = max(border_cols) + 1
    out = [row[:panel_w] for row in grid]

    # Extract colored shapes from the objects to the right of the panel.
    objects = []
    seen = set()
    for r in range(h):
        for c in range(panel_w, w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                rr, cc = stack.pop()
                cells.append((rr, cc))
                for nr, nc in ((rr-1,cc), (rr+1,cc), (rr,cc-1), (rr,cc+1)):
                    if (0 <= nr < h and panel_w <= nc < w and
                        grid[nr][nc] == color and (nr,nc) not in seen):
                        seen.add((nr,nc))
                        stack.append((nr,nc))
            mr = min(a for a, b in cells)
            mc = min(b for a, b in cells)
            shape = frozenset((a-mr, b-mc) for a, b in cells)
            objects.append((shape, color))

    # Horizontal frame bars divide the panel into cavities.
    bars = [r for r in range(h) if all(grid[r][c] == frame for c in range(panel_w))]
    for top, bottom in zip(bars, bars[1:]):
        cavity = {(r-top-1, c-1)
                  for r in range(top+1, bottom)
                  for c in range(1, panel_w-1)
                  if grid[r][c] != frame}
        if not cavity:
            continue
        for shape, color in objects:
            if shape == frozenset(cavity):
                for r in range(top+1, bottom):
                    for c in range(1, panel_w-1):
                        if grid[r][c] != frame:
                            out[r][c] = color
                break
    return out
